<?php require_once '../conexao.php';require_once '../includes/rbac.php';require_once '../includes/flash.php';exigirCargo(['administrador','diretor']);if($_SERVER['REQUEST_METHOD']==='POST'){$nome=trim($_POST['nome']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$senha=$_POST['senha']??'';$conf=$_POST['confirmar']??'';if(mb_strlen($nome)<3||!$email)flash('error','Informe nome e e-mail válidos.');elseif(!preg_match('/^(?=.*\d)(?=.*[^A-Za-z0-9]).{8,}$/',$senha))flash('error','A senha precisa ter no mínimo 8 caracteres, 1 número e 1 caractere especial.');elseif($senha!==$conf)flash('error','As senhas não coincidem.');else try{$s=$pdo->prepare("INSERT INTO usuarios(nome,email,senha,cargo,ativo) VALUES(?,?,?,'administrador',1)");$s->execute([$nome,$email,password_hash($senha,PASSWORD_DEFAULT)]);flash('success','Administrador criado com sucesso.');}catch(Throwable $e){flash('error','Não foi possível criar o administrador. O e-mail pode já estar em uso.');}header('Location:administradores.php');exit;}$u=$pdo->query("SELECT nome,email,ativo,criado_em FROM usuarios WHERE cargo='administrador' ORDER BY nome")->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administradores | Aura</title><link rel="icon" type="image/png" sizes="512x512" href="../img/favicon-aura.png"><link rel="shortcut icon" href="../img/favicon.ico"><link rel="stylesheet" href="../css/style.css"></head><body><header class="header"><div class="container nav"><a href="index.php" class="brand"><img src="../img/logo-aura-oficial.png"></a><a class="back-link" href="index.php">← Painel</a></div></header><main class="panel-page"><div class="container"><p class="eyebrow">SEGURANÇA</p><h1 class="admin-title">Administradores</h1><?php mostrarFlash();?><form method="post" class="form-card admin-form"><label>Nome</label><input name="nome" required><label>E-mail</label><input type="email" name="email" required><label>Senha</label><input type="password" name="senha" minlength="8" autocomplete="new-password" required><label>Confirmar senha</label><input type="password" name="confirmar" minlength="8" autocomplete="new-password" required><p class="muted">Mínimo 8 caracteres, incluindo pelo menos 1 número e 1 caractere especial.</p><button class="btn">Adicionar administrador</button></form><div class="table-wrapper"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Status</th><th>Criado em</th></tr></thead><tbody><?php foreach($u as $x):?><tr><td><?=htmlspecialchars($x['nome'])?></td><td><?=htmlspecialchars($x['email'])?></td><td><?=$x['ativo']?'Ativo':'Inativo'?></td><td><?=date('d/m/Y',strtotime($x['criado_em']))?></td></tr><?php endforeach;?></tbody></table></div></div></main><script src="../js/app.js"></script></body></html>
